"""Merge user data from three heterogeneous sources into one Parquet dataset."""

import json
import re
from datetime import date, datetime

import pandas as pd

SOURCES = [
    ("source_a", "/data/source_a/users.json"),
    ("source_b", "/data/source_b/users.csv"),
    ("source_c", "/data/source_c/users.parquet"),
]

# Canonical field -> possible names, in no significant order.
FIELD_ALIASES = {
    "user_id": ["user_id", "id", "userId"],
    "name": ["full_name", "name", "userName"],
    "email": ["email", "email_address"],
    "created_date": ["registration_date", "created_at", "joined"],
    "status": ["status", "is_active", "active"],
}

OUTPUT_COLUMNS = ["user_id", "name", "email", "created_date", "status"]


def read_source(path):
    if path.endswith(".json"):
        return pd.read_json(path)
    if path.endswith(".csv"):
        return pd.read_csv(path)
    if path.endswith(".parquet"):
        return pd.read_parquet(path)
    raise ValueError(f"Unsupported source format: {path}")


def canonicalize(df):
    """Rename source-specific columns to canonical names."""
    renamed = {}
    for canonical, aliases in FIELD_ALIASES.items():
        for alias in aliases:
            if alias in df.columns and alias not in renamed:
                renamed[alias] = canonical
                break
    df = df.rename(columns=renamed)
    for column in OUTPUT_COLUMNS:
        if column not in df.columns:
            df[column] = None
    return df[OUTPUT_COLUMNS]


def normalize_status(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    text = str(value).strip().lower()
    if text in {"true", "1", "yes", "y", "active"}:
        return "active"
    if text in {"false", "0", "no", "n", "inactive"}:
        return "inactive"
    return text


DATE_FORMATS = ("%Y-%m-%d", "%Y/%m/%d", "%d-%m-%Y", "%d/%m/%Y", "%m/%d/%Y")


def normalize_date(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    if isinstance(value, (pd.Timestamp, datetime, date)):
        return value.strftime("%Y-%m-%d")
    text = str(value).strip()
    for fmt in DATE_FORMATS:
        try:
            return datetime.strptime(text, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue
    # Handle ISO timestamps such as 2024-01-15T00:00:00.
    match = re.match(r"^(\d{4}-\d{2}-\d{2})", text)
    if match:
        return match.group(1)
    return None


def normalize_user_id(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    return int(value)


def normalize_record(record):
    return {
        "user_id": normalize_user_id(record.get("user_id")),
        "name": None if pd.isna(record.get("name")) else str(record.get("name")).strip(),
        "email": None if pd.isna(record.get("email")) else str(record.get("email")).strip(),
        "created_date": normalize_date(record.get("created_date")),
        "status": normalize_status(record.get("status")),
    }


def main():
    # user_id -> {source_name: normalized record}
    by_user = {}
    source_order = [name for name, _ in SOURCES]

    for source_name, path in SOURCES:
        df = canonicalize(read_source(path))
        for raw in df.to_dict(orient="records"):
            record = normalize_record(raw)
            user_id = record["user_id"]
            if user_id is None:
                continue
            by_user.setdefault(user_id, {})[source_name] = record

    merged_rows = []
    conflicts = []

    for user_id in sorted(by_user):
        records = by_user[user_id]
        merged = {"user_id": user_id}

        for field in ["name", "email", "created_date", "status"]:
            # Values from each source that actually carries this user/field.
            values = {
                source: records[source][field]
                for source in source_order
                if source in records and records[source][field] is not None
            }

            selected = None
            for source in source_order:  # Highest priority first.
                if source in values:
                    selected = values[source]
                    break
            merged[field] = selected

            if len(set(values.values())) > 1:
                conflicts.append(
                    {
                        "user_id": user_id,
                        "field": field,
                        "values": values,  # only sources where the value exists
                        "selected": selected,
                    }
                )

        merged_rows.append(merged)

    output = pd.DataFrame(merged_rows, columns=OUTPUT_COLUMNS)
    output["user_id"] = output["user_id"].astype("int64")
    for column in ["name", "email", "created_date", "status"]:
        output[column] = output[column].astype("string")

    output.to_parquet("/app/merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w", encoding="utf-8") as handle:
        json.dump(report, handle, indent=2)

    print(output.to_string(index=False))
    print(f"\nusers={len(output)} conflicts={len(conflicts)}")


if __name__ == "__main__":
    main()
